public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }
    // Remove leading '/' if present (absolute path)
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }
    // Split the path into segments
    String[] parts = rawPath.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String decoded = part;
        if (decode) {
            try {
                decoded = java.net.URLDecoder.decode(part, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (Exception e) {
                // If decoding fails, keep the original percent-encoded segment
                decoded = part;
            }
        }
        // Create a PathSegmentImpl instance (assumes a constructor that accepts the decoded value)
        segments.add(new PathSegmentImpl(decoded));
    }
    return segments;
}

