        while (descriptor.charAt(index) != ')') {
            // parse a type
            if (descriptor.charAt(index) == '[') {
                // array type: skip all '['
                while (descriptor.charAt(index) == '[') {
                    index++;
                }
                // then object or primitive
                if (descriptor.charAt(index) == 'L') {
                    // object type: skip until ';'
                    index++;
                    while (descriptor.charAt(index) != ';') {
                        index++;
                    }
                    index++; // skip ';'
                } else {
                    // primitive type
                    index++;
                }
            } else if (descriptor.charAt(index) == 'L') {
                // object type
                index++;
                while (descriptor.charAt(index) != ';') {
