protected int removeUnusedNodes(){
    int removed = 0;
    if (root == null) return 0;
    class NodeInfo{ CategoryNode node; CategoryNode parent; NodeInfo(CategoryNode n, CategoryNode p){node=n;parent=p;}}
    java.util.Deque<NodeInfo> stack = new java.util.ArrayDeque<>();
    stack.push(new NodeInfo(root, null));
    while (!stack.isEmpty()){
        NodeInfo info = stack.pop();
        CategoryNode node = info.node;
        CategoryNode parent = info.parent;
        if (!node.isActive()){
            if (parent != null){
                parent.removeChild(node);
                removed++;
            } else {
                root = null;
                removed++;
            }
            continue;
        }
        java.util.List<CategoryNode> children = node.getChildren();
        for (int i = children.size() - 1; i >= 0; i--){
            stack.push(new NodeInfo(children.get(i), node));
        }
    }
    return removed;
}

