protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || tour.isEmpty()){
        return null;
    }
    Set<E> remaining = new HashSet<>(tour);
    List<E> edgeList = new ArrayList<>();
    List<V> vertexList = new ArrayList<>();

    // pick an arbitrary starting edge
    E firstEdge = remaining.iterator().next();
    V startVertex = graph.getEdgeSource(firstEdge);
    V current = startVertex;
    vertexList.add(startVertex);
    remaining.remove(firstEdge);
    edgeList.add(firstEdge);
    V next = graph.getEdgeTarget(firstEdge);
    vertexList.add(next);
    current = next;

    while (!remaining.isEmpty()){
        boolean found = false;
        for (E e : remaining){
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(current)){
                edgeList.add(e);
                current = tgt;
                vertexList.add(current);
                remaining.remove(e);
                found = true;
                break;
            } else if (tgt.equals(current)){
                edgeList.add(e);
                current = src;
                vertexList.add(current);
                remaining.remove(e);
                found = true;
                break;
            }
        }
        if (!found){
            // cannot continue the tour
            return null;
        }
    }

    return new GraphPathImpl<>(graph, startVertex, current, edgeList, vertexList);
}

