private void moveAllListNodes(DoublyLinkedList<E> list){
    // Ensure atomicity by locking both lists
    synchronized (this) {
        synchronized (list) {
            // Start with the first node of the source list
            ListNodeImpl<E> node = (ListNodeImpl<E>) list.getFirstNode();
            while (node != null) {
                // Keep a reference to the next node before removal
                ListNodeImpl<E> next = (ListNodeImpl<E>) node.getNext();
                // Remove the node from the source list
                removeListNode(node);
                // Add the node to this list
                addListNode(node);
                // Move to the next node
                node = next;
            }
        }
    }
}

